import{_ as o,o as c,c as t,a3 as d}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Toolchain Structure","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Toolchain Structure | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/toolchain"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/toolchain"}]]},"headers":[],"relativePath":"xclang/design/toolchain.md","filePath":"en/xclang/design/toolchain.md","lastUpdated":1794509097000}'),a={name:"xclang/design/toolchain.md"};function i(l,e,n,s,r,h){return c(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="toolchain-structure" tabindex="-1">Toolchain Structure <a class="header-anchor" href="#toolchain-structure" aria-label="Permalink to &quot;Toolchain Structure&quot;">​</a></h1><p><code>clang</code> locates each target&#39;s sysroot, headers, runtimes and linker through a plain-text config file in <code>bin/</code> rather than defaults compiled into the compiler. <code>clang</code>, <code>lld</code> and most binary tools share one multicall executable (<code>llvm</code>), and the sysroots and shared headers are plain directories without symbolic links on Windows or in the Linux sysroots. Passing <code>--target=&lt;triple&gt;</code> is therefore the whole difference between a native and a cross build, <code>-stdlib=platform</code> switches to the platform&#39;s C++ library, and <code>--no-default-config</code> restores a bare upstream <code>clang</code> (<a href="./../guide/cross-compiling#how-clang-finds-a-target-s-files">cross-compiling</a>, <a href="./../reference/layout">archive layout</a>).</p><h2 id="a-config-file-per-target" tabindex="-1">A Config File per Target <a class="header-anchor" href="#a-config-file-per-target" aria-label="Permalink to &quot;A Config File per Target&quot;">​</a></h2><p>When compiling or linking for a target, <code>clang</code> searches <code>bin/</code> next to its own executable for <code>&lt;triple&gt;.cfg</code> (<code>clang-cl</code> searches for <code>&lt;triple&gt;-clang-cl.cfg</code>) and prepends the file&#39;s flags to the command line. For <code>--target=aarch64-w64-mingw32</code>, <code>clang</code> normalizes the triple and reads <code>aarch64-w64-windows-gnu.cfg</code>. <code>toolchain/common.ts</code> writes a config file into <code>bin/</code> for every accepted spelling of each target:</p><table tabindex="0"><thead><tr><th>target</th><th>config files in <code>bin/</code></th></tr></thead><tbody><tr><td>Linux (glibc)</td><td><code>&lt;arch&gt;-unknown-linux-gnu.cfg</code>, <code>&lt;arch&gt;-pc-linux-gnu.cfg</code></td></tr><tr><td>Linux (musl)</td><td><code>&lt;arch&gt;-unknown-linux-musl.cfg</code>, <code>&lt;arch&gt;-pc-linux-musl.cfg</code></td></tr><tr><td>Windows (MinGW)</td><td><code>&lt;arch&gt;-w64-windows-gnu.cfg</code>, <code>&lt;arch&gt;-pc-windows-gnu.cfg</code></td></tr><tr><td>macOS</td><td><code>&lt;arch&gt;-apple-darwin.cfg</code>, <code>&lt;arch&gt;-apple-macos.cfg</code>, <code>&lt;arch&gt;-apple-macosx.cfg</code></td></tr><tr><td>Windows (MSVC)</td><td><code>&lt;arch&gt;-pc-windows-msvc.cfg</code>, <code>&lt;arch&gt;-unknown-windows-msvc.cfg</code>, and for <code>clang-cl</code> <code>&lt;spelling&gt;-clang-cl.cfg</code></td></tr></tbody></table><p><code>&lt;arch&gt;</code> is <code>x86_64</code>, or for 64-bit Arm both <code>aarch64</code> and <code>arm64</code>. Because <code>compiler-rt</code> installs its libraries under the canonical <code>&lt;arch&gt;-unknown-linux-*</code> and <code>&lt;arch&gt;-w64-windows-gnu</code> directory names, <a href="./../reference/patches">patch 0013</a> maps the <code>-pc-</code> and <code>arm64-</code> spellings of the Linux and MinGW targets back to that runtime directory.</p><p>Each target config file sets the following options (<a href="https://github.com/clice-io/xclang/tree/main/toolchain/config" target="_blank" rel="noreferrer"><code>toolchain/config/</code></a>):</p><table tabindex="0"><thead><tr><th>target</th><th>options in <code>&lt;spelling&gt;.cfg</code></th></tr></thead><tbody><tr><td>Linux (glibc)</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>, <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-static-libstdc++ -static-libgcc</code>, <code>-fuse-ld=lld</code></td></tr><tr><td>Linux (musl)</td><td>the same with <code>-static</code> in place of <code>-static-libstdc++ -static-libgcc</code>, linking <code>musl</code> statically as well (<a href="./../guide/cross-compiling#musl-targets">musl targets</a>)</td></tr><tr><td>Windows (MinGW)</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>, <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-idirafter &lt;CFGDIR&gt;/../mingw-w64/include</code>, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-fuse-ld=lld</code> (the sysroot contains static libraries only)</td></tr><tr><td>macOS</td><td>on Linux and Windows hosts <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code> (on macOS hosts Xcode&#39;s SDK); <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code>; <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> (placing <code>libc++.a</code> ahead of the SDK&#39;s <code>libc++.tbd</code>), and <code>-B&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> for <code>libc++.modules.json</code> (<a href="./macos">macOS</a>)</td></tr><tr><td>Windows (MSVC)</td><td>on Linux and macOS hosts <code>-Xmicrosoft-windows-sys-root &lt;CFGDIR&gt;/../sdk/windows</code> (<code>/winsysroot</code> in <code>clang-cl</code>); <code>@&lt;triple&gt;-sdk.cfg</code> (<code>@&lt;triple&gt;-clang-cl-sdk.cfg</code>), rewritten by <code>xclang sdk</code> to include the active SDK&#39;s version config; <code>-fuse-ld=lld</code>; object directives for <code>clang_rt.builtins-&lt;arch&gt;.lib</code> and the hybrid CRT (<code>--linker-option=/nodefaultlib:libucrt.lib</code>, <code>--dependent-lib=ucrt.lib</code>); <code>-D_STATIC_INLINE_UCRT_FUNCTIONS=0</code>; and <code>-stdlib++-isystem</code> (<code>/clang:-stdlib++-isystem</code> in <code>clang-cl</code>, silenced on C compiles by <a href="./../reference/patches">patch 0011</a>) for <code>libc++</code> (<a href="./windows#config-files-and-object-directives">Windows</a>)</td></tr></tbody></table><p><code>&lt;CFGDIR&gt;</code> expands to <code>bin/</code>, so the toolchain works from any unpacked directory without modification. Because <code>clang</code> loads the config file for the host&#39;s default target as well, a native <code>clang++ main.cpp</code> on Linux compiles against the bundled glibc 2.17 sysroot and links <code>libc++</code> statically.</p><p>Two additional config-file rules avoid surprises in <code>clang-cl</code> and Bazel:</p><ul><li><strong><code>clang-cl</code> defaults to the host architecture&#39;s MSVC target.</strong> When run without <code>--target</code>, <code>clang-cl</code> searches for <code>&lt;default-target&gt;-clang-cl.cfg</code> and <code>&lt;default-target&gt;.cfg</code> before switching to an MSVC triple. <code>toolchain/common.ts</code> writes the MSVC <code>clang-cl</code> config of <code>&lt;arch&gt;</code> to <code>&lt;spelling&gt;-clang-cl.cfg</code> (and <code>&lt;spelling&gt;-clang-cl-system.cfg</code>) for every target spelling, so a plain <code>clang-cl</code> builds for <code>&lt;arch&gt;-pc-windows-msvc</code> instead of reading the host target&#39;s GNU flags.</li><li><strong>Bazel rewrites the config files with relative paths.</strong> <code>clang</code> expands <code>&lt;CFGDIR&gt;</code> to an absolute path, which enters <code>.d</code> dependency files and breaks cross-machine action caching. The Bazel module writes copies of the config files under <code>cfg/</code> with paths relative to the execution root and passes <code>--no-default-config --config=&lt;file&gt;</code> (<a href="./bazel-module#no-absolute-paths">no absolute paths</a>).</li></ul><h3 id="the-platform-s-c-library" tabindex="-1">The Platform&#39;s C++ Library <a class="header-anchor" href="#the-platform-s-c-library" aria-label="Permalink to &quot;The Platform&#39;s C++ Library&quot;">​</a></h3><p>Every <code>&lt;spelling&gt;.cfg</code> has a companion <code>&lt;spelling&gt;-system.cfg</code> (and <code>&lt;spelling&gt;-clang-cl-system.cfg</code>). Passing any <code>-stdlib=</code> value other than <code>libc++</code> (<code>-stdlib=platform</code> or <code>-stdlib=libstdc++</code>; in <code>clang-cl</code>, <code>/clang:-stdlib=platform</code>) selects <code>&lt;spelling&gt;-system.cfg</code> in place of <code>&lt;spelling&gt;.cfg</code> (<a href="./../reference/patches">patch 0018</a>, <a href="./../guide/cross-compiling#the-platform-s-c-library">cross-compiling</a>):</p><table tabindex="0"><thead><tr><th>target</th><th>options in <code>&lt;spelling&gt;-system.cfg</code></th></tr></thead><tbody><tr><td>Linux (glibc), Linux (musl), Windows (MinGW)</td><td><code>-fuse-ld=lld</code> only; the C and C++ libraries come from the host, a distribution&#39;s cross packages, or <code>--sysroot</code></td></tr><tr><td>macOS</td><td>the SDK (<code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code> on Linux and Windows hosts), <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code>, linking the SDK&#39;s <code>libc++.tbd</code></td></tr><tr><td>Windows (MSVC)</td><td>the MSVC target config without <code>-stdlib++-isystem</code>, using Microsoft&#39;s STL from the fetched SDK or Visual Studio</td></tr></tbody></table><p>Switching config files is necessary because flags in <code>&lt;spelling&gt;.cfg</code> cannot be undone later on the command line: <code>-stdlib++-isystem</code> adds <code>libc++</code> headers regardless of <code>-stdlib=</code>, <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> on macOS puts <code>libc++.a</code> before the SDK&#39;s <code>libc++.tbd</code>, and the bundled Linux and MinGW sysroots do not carry <code>libstdc++</code>.</p><h3 id="why-not-built-in-defaults" tabindex="-1">Why Not Built-In Defaults <a class="header-anchor" href="#why-not-built-in-defaults" aria-label="Permalink to &quot;Why Not Built-In Defaults&quot;">​</a></h3><p>LLVM can compile defaults for the C++ library, compiler runtime, unwinder and linker directly into the driver (<code>CLANG_DEFAULT_CXX_STDLIB</code>, <code>CLANG_DEFAULT_RTLIB</code>, <code>CLANG_DEFAULT_UNWINDLIB</code>, <code>CLANG_DEFAULT_LINKER</code>), as xclang 23.1.2.1 did. Those settings are compiled into <code>clangDriver</code>, which is also part of <code>libclang</code>.</p><p>Tools built on <code>libclang</code> (such as clice) run <code>clangDriver</code> to compute include paths from <code>compile_commands.json</code> entries for other compilers. With defaults compiled into <code>clangDriver</code>, a <code>g++</code> command in a compilation database received xclang&#39;s <code>libc++</code> include paths instead of <code>libstdc++</code>&#39;s.</p><p>Keeping those <code>CLANG_DEFAULT_*</code> variables unset in <code>toolchain/cmake/caches/clang.cmake</code> and placing the defaults in <code>bin/*.cfg</code> separates the two: <code>bin/clang</code> reads <code>bin/&lt;triple&gt;.cfg</code>, while <code>clangDriver</code> linked inside a <code>libclang</code> tool has no <code>bin/*.cfg</code> and behaves like upstream <code>clang</code>.</p><h3 id="the-bare-compiler" tabindex="-1">The Bare Compiler <a class="header-anchor" href="#the-bare-compiler" aria-label="Permalink to &quot;The Bare Compiler&quot;">​</a></h3><p>Passing <code>--no-default-config</code> tells <code>clang</code> to ignore <code>bin/&lt;triple&gt;.cfg</code>. <code>clang</code> then searches the host system&#39;s headers and libraries and invokes the system linker, just as an unconfigured upstream build does (<code>toolchain/sysroot.ts</code> and <code>toolchain/runtimes.ts</code> use <code>--no-default-config</code> when building the sysroots and <code>libc++</code> themselves).</p><h2 id="one-program" tabindex="-1">One Program <a class="header-anchor" href="#one-program" aria-label="Permalink to &quot;One Program&quot;">​</a></h2><p><code>toolchain/cmake/caches/clang.cmake</code> sets <code>LLVM_TOOL_LLVM_DRIVER_BUILD=ON</code>, which builds <code>clang</code>, <code>clang-scan-deps</code>, <code>lld</code> and most binary tools (<code>llvm-ar</code>, <code>llvm-ranlib</code>, <code>llvm-lib</code>, <code>llvm-dlltool</code>, <code>llvm-nm</code>, <code>llvm-objcopy</code>, <code>llvm-strip</code>, <code>llvm-install-name-tool</code>, <code>llvm-objdump</code>, <code>llvm-readobj</code>, <code>llvm-rc</code>, <code>llvm-windres</code>, <code>llvm-symbolizer</code>, <code>dsymutil</code>, <code>llvm-gsymutil</code>, <code>llvm-libtool-darwin</code>, <code>llvm-lipo</code>, ...) into one multicall executable, <code>bin/llvm</code> (<code>bin/llvm.exe</code> on Windows).</p><p>Instead of each binary carrying a separate copy of the LLVM libraries, every tool name in <code>bin/</code> is a symbolic link to <code>llvm</code> on Linux and macOS, or a small launcher compiled from <a href="https://github.com/clice-io/xclang/blob/main/toolchain/launcher/alias.c" target="_blank" rel="noreferrer"><code>toolchain/launcher/alias.c</code></a> on Windows that starts <code>llvm.exe &lt;tool-name&gt; &lt;arguments&gt;</code> inside a kill-on-close job object (<a href="./windows#the-launchers">the launchers</a>). Together with omitting glibc&#39;s <code>locale-archive</code>, linking with safe identical code folding (<code>-Wl,--icf=safe -Wl,-O2</code> on Linux and Windows), and compressing all host archives with <code>.tar.xz</code>, each host toolchain archive is about 100 MB (<a href="./../reference/releases#assets">releases</a>).</p><p>Linking the tools against a shared <code>libLLVM</code> (<code>LLVM_LINK_LLVM_DYLIB</code>) would also share code, but was rejected for compile speed: calls across a shared library boundary go through dynamic linker tables, and ThinLTO cannot inline or optimize across it.</p><p>Five tools that LLVM&#39;s multicall driver build does not include are compiled as standalone binaries in <code>bin/</code>: <code>llvm-profdata</code>, <code>llvm-cov</code>, <code>llvm-dwarfdump</code>, <code>llvm-strings</code> and <code>FileCheck</code>.</p><h3 id="what-prints" tabindex="-1">What <code>-###</code> Prints <a class="header-anchor" href="#what-prints" aria-label="Permalink to &quot;What `-###` Prints&quot;">​</a></h3><p>Because <code>clang</code> is dispatched by the multicall <code>llvm</code> binary, <code>clang -###</code> prints its <code>-cc1</code> command with <code>llvm</code> as the program and <code>&quot;clang&quot;</code> before <code>&quot;-cc1&quot;</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/path/xclang/bin/llvm&quot; &quot;clang&quot; &quot;-cc1&quot; ...</span></span></code></pre></div><p>Tools that parse <code>clang -###</code> output must scan for <code>&quot;-cc1&quot;</code> rather than assuming <code>&quot;-cc1&quot;</code> is the first argument after the executable path.</p><h2 id="plain-directories" tabindex="-1">Plain Directories <a class="header-anchor" href="#plain-directories" aria-label="Permalink to &quot;Plain Directories&quot;">​</a></h2><p>Each target&#39;s sysroot (<code>&lt;toolchain&gt;/&lt;triple&gt;/</code>) is a plain directory containing only what compiling and linking read: headers, startup files, C runtime libraries, <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code> and the <a href="./hermeticity#gcc-library-names">GCC stub archives</a>, while <code>compiler-rt</code> lives in <code>lib/clang/&lt;major&gt;/lib/</code> (<a href="./../reference/layout">archive layout</a>).</p><p>Headers that are identical across targets are stored once without symbolic links (<code>shareHeaders</code> in <code>toolchain/common.ts</code>): <code>libc++/include/c++/v1</code> for all targets, <code>libc++/include/&lt;normalized-triple&gt;/c++/v1</code> for each target&#39;s <code>__config_site</code> (and <code>cxxabi.h</code> on non-MSVC targets), and <code>mingw-w64/include</code> for both MinGW targets (<a href="./../reference/layout#shared-headers">shared headers</a>). <code>toolchain/package.ts</code> verifies that Windows toolchain archives contain no symbolic links and that no archive contains two paths differing only in case (<a href="./hermeticity#why-glibc-2-17">why glibc 2.17</a>).</p><p>Nothing in the sysroots or <code>compiler-rt</code> directory is specific to xclang&#39;s build of <code>clang</code>. Any upstream <code>clang</code> of the same major version can cross-compile against a target directory when given <code>--sysroot</code> and <code>-resource-dir</code>.</p>',34)])])}const m=o(a,[["render",i]]);export{p as __pageData,m as default};
